import 'package:flutter/material.dart';import 'package:flutter_test/flutter_test.dart';import 'package:repo_aksomda_lifetownnightclub/features/auth/domain/usecases/login.dart';import 'package:repo_aksomda_lifetownnightclub/features/auth/domain/usecases/logout.dart';import 'package:repo_aksomda_lifetownnightclub/features/auth/domain/usecases/register.dart';import 'package:repo_aksomda_lifetownnightclub/features/auth/presentation/controllers/auth_controller.dart';import 'package:repo_aksomda_lifetownnightclub/features/auth/presentation/pages/register_page.dart';import 'mocks/mock_auth_repository.dart';
void main(){testWidgets('inscription utilise bien les champs nom, prénom, âge et téléphone',(tester)async{final repo=MockAuthRepository();final controller=AuthController(loginUseCase:Login(repo),registerUseCase:Register(repo),logoutUseCase:Logout(repo));var back=false;await tester.pumpWidget(MaterialApp(home:RegisterPage(controller:controller,onLogin:()=>back=true)));final fields=find.byType(TextFormField);await tester.enterText(fields.at(0),'Somda');await tester.enterText(fields.at(1),'Clément');await tester.enterText(fields.at(2),'30');await tester.enterText(fields.at(3),'70000000');await tester.enterText(fields.at(4),'c@x.com');await tester.enterText(fields.at(5),'password');await tester.tap(find.text('Créer le compte'));await tester.pumpAndSettle();expect(repo.currentUser?.prename,'Clément');expect(repo.currentUser?.telephone,'70000000');expect(back,true);});}
